"use client";
import {
  forwardRef,
  useLayoutEffect,
  useImperativeHandle,
  useRef,
  useState,
  type TextareaHTMLAttributes,
  type ReactNode,
  type Ref,
} from "react";
import { cx } from "../../utils/cx";
import { Group, TextArea as AriaTextArea } from "react-aria-components";
import { TextField } from "../input/input";
import { Label } from "../input/label";
import { HintText } from "../input/hint-text";
import { INPUT_FIELD_SURFACE, inputFieldStateClasses } from "../input/field-surface";
export interface TextareaProps extends TextareaHTMLAttributes<HTMLTextAreaElement> {
  ref?: Ref<HTMLTextAreaElement>;
  autoResize?: boolean;
  maxRows?: number;
  resize?: "none" | "vertical" | "horizontal" | "both";
}
/** Multiline field using the same semantic paint, typography and focus ring as InputBase. */
export const Textarea = forwardRef<HTMLTextAreaElement, Omit<TextareaProps, "ref">>(function Textarea({ className, autoResize = false, maxRows, resize: resizeMode = "vertical", onInput, ...props }, ref) {
  const element = useRef<HTMLTextAreaElement | null>(null), ownedMax = useRef<string | undefined>(undefined), wasAuto = useRef(false);
  useImperativeHandle(ref, () => element.current!, []);
  const measure = useRef(() => {});
  measure.current = () => {
    const field = element.current;
    if (!field) return;
    const requestedMax = typeof props.style?.maxHeight === "number" ? `${props.style.maxHeight}px` : props.style?.maxHeight ?? "";
    if (ownedMax.current && field.style.maxHeight === ownedMax.current) field.style.maxHeight = requestedMax;
    ownedMax.current = undefined;
    if (!autoResize) {
      ownedMax.current = undefined;
      if (wasAuto.current) { field.style.height = typeof props.style?.height === "number" ? `${props.style.height}px` : props.style?.height ?? ""; field.style.overflowY = props.style?.overflowY ?? ""; wasAuto.current = false; }
      return;
    }
    wasAuto.current = true;
    const computed = getComputedStyle(field), line = parseFloat(computed.lineHeight) || 20;
    const padding = (parseFloat(computed.paddingTop) || 0) + (parseFloat(computed.paddingBottom) || 0);
    const border = (parseFloat(computed.borderTopWidth) || 0) + (parseFloat(computed.borderBottomWidth) || 0);
    const rows = Math.max(1, props.rows ?? 2), minimum = rows * line + padding + border;
    const rowMaximum = !Number.isFinite(maxRows) ? Infinity : Math.max(rows, maxRows!) * line + padding + border;
    const cssMaximum = computed.maxHeight.endsWith("px") ? parseFloat(computed.maxHeight) : Infinity;
    const maximum = Math.min(rowMaximum, cssMaximum);
    field.style.height = "0px";
    const content = field.scrollHeight + border;
    field.style.height = `${Math.min(maximum, Math.max(minimum, content))}px`;
    field.style.overflowY = content > maximum ? "auto" : "hidden";
    if (Number.isFinite(rowMaximum)) { ownedMax.current = `${maximum}px`; field.style.maxHeight = ownedMax.current; }
  };
  useLayoutEffect(() => measure.current(), [props.value, props.defaultValue, props.rows, autoResize, maxRows]);
  useLayoutEffect(() => {
    if (!autoResize || !element.current || typeof ResizeObserver === "undefined") return;
    const field = element.current; let width = field.clientWidth;
    const observer = new ResizeObserver(() => { if (width !== field.clientWidth) { width = field.clientWidth; measure.current(); } });
    observer.observe(field); return () => observer.disconnect();
  }, [autoResize]);
  return (
    <AriaTextArea
      {...props}
      ref={element}
      onInput={(event) => { measure.current(); onInput?.(event); }}
      className={cx(
        "block w-full rounded-2lg bg-background-tertiary-default px-2.5 py-1.5 text-body-regular text-text-primary outline-none placeholder:text-text-tertiary disabled:cursor-not-allowed disabled:text-input-disabled-text focus-visible:ring-2 focus-visible:ring-border-focus-ring",
        autoResize || resizeMode === "none" ? "resize-none" : resizeMode === "both" ? "resize" : resizeMode === "horizontal" ? "resize-x" : "resize-y",
        className,
      )}
    />
  );
});

export interface TextareaFieldProps extends TextareaProps {
  fieldClassName?: string;
  rootClassName?: string;
  isInvalid?: boolean;
  isDisabled?: boolean;
  isRequired?: boolean;
  label?: ReactNode;
  hint?: ReactNode;
  tooltip?: boolean | string;
  size?: "medium" | "small";
  showCount?: boolean;
  /** String callback in addition to the existing native change event. */
  onValueChange?: (value: string) => void;
}
/** Shared field composition; native callbacks remain compatible with compact editors. */
export const TextareaField = forwardRef<HTMLTextAreaElement, Omit<TextareaFieldProps, "ref">>(function TextareaField({ fieldClassName, rootClassName, isInvalid: invalid, isDisabled, isRequired, label, hint, tooltip, size = "medium", showCount = false, onValueChange, value, defaultValue, rows, className, disabled, required, ...props }, ref) {
  const [draft, setDraft] = useState(() => String(value ?? defaultValue ?? ""));
  const text = value === undefined ? draft : String(value);
  const isInvalid = invalid ?? (props["aria-invalid"] === true || props["aria-invalid"] === "true");
  const disabledState = isDisabled ?? disabled, requiredState = isRequired ?? required;
  const rowCount = rows ?? (label !== undefined || hint !== undefined || showCount ? 3 : undefined);
  return (
    <TextField id={props.id} data-input-size={size} aria-label={props["aria-label"]} aria-labelledby={props["aria-labelledby"]}
      isDisabled={disabledState} isRequired={requiredState} isInvalid={isInvalid}
      value={text} onChange={next => { setDraft(next); onValueChange?.(next); }}
      className={cx("group flex h-max w-full flex-col items-start gap-1", rootClassName)}>
      {label !== undefined && label !== null && <Label isRequired={requiredState} tooltip={tooltip}>{label}</Label>}
      <Group role="presentation" isDisabled={disabledState} isInvalid={isInvalid}
        className={(state) => cx(INPUT_FIELD_SURFACE, inputFieldStateClasses(state), "flex-col items-stretch", size === "small" ? "px-1.5 py-2" : "p-2", fieldClassName)}>
        <Textarea ref={ref} {...props} rows={rowCount} value={text} disabled={disabledState} required={requiredState} aria-invalid={isInvalid || props["aria-invalid"]}
          className={cx("m-0 min-w-0 rounded-none border-0 bg-transparent p-0 px-1 font-sans focus:placeholder:text-text-primary focus-visible:ring-0 disabled:placeholder:text-input-disabled-text aria-invalid:placeholder:text-text-error-placeholder", className)} />
      </Group>
      {(hint !== undefined && hint !== null || showCount) && <div className="flex w-full items-start justify-between gap-3">
        {hint !== undefined && hint !== null && <HintText isInvalid={isInvalid}>{hint}</HintText>}
        {showCount && <span className="ms-auto shrink-0 pt-px text-caption-1-medium tabular-nums text-text-tertiary">{text.length}{props.maxLength === undefined ? "" : `/${props.maxLength}`}</span>}
      </div>}
    </TextField>
  );
});
